const fs = require('fs');
const dirs = fs.readdirSync('.').filter(d => /^[0-9]+_/.test(d));
const nodes = {};
for (const d of dirs) {
  const s = require('./' + d + '/snapshot.json');
  nodes[s.id] = { folder: d, prevIds: s.prevIds };
}
const parents = {};
let unreferenced = [];
const referenced = new Set();
for (const [id, n] of Object.entries(nodes)) {
  for (const p of n.prevIds) {
    if (!nodes[p]) { console.log('!! prevId', p, 'of', id, '('+n.folder+') points to MISSING snapshot'); continue; }
    (parents[p] = parents[p] || []).push(id);
    referenced.add(id);
  }
}
for (const id of Object.keys(nodes)) if (!referenced.has(id)) unreferenced.push(id);
console.log('total snapshots:', Object.keys(nodes).length);
console.log('heads (unreferenced):', unreferenced.map(id => nodes[id].folder + ' ' + id));
let branched = [];
for (const [pid, kids] of Object.entries(parents)) if (kids.length > 1) branched.push([nodes[pid]?.folder, kids.length]);
console.log('snapshots referenced by >1 child (branched):', branched.length ? JSON.stringify(branched) : 'NONE');
"

